using System.Text.Json;
namespace SoloCamera.Windows;
public static class ObsDiagnostics {
 public static async Task Run(string configFile,string report){try{using var config=JsonDocument.Parse(await File.ReadAllTextAsync(configFile));using var obs=new ObsBridge();await obs.Connect(config.RootElement.GetProperty("server_port").GetInt32(),config.RootElement.GetProperty("server_password").GetString()!);var stats=await obs.Request("GetStats");var video=await obs.Request("GetVideoSettings");var webcam=await obs.Request("GetVirtualCamStatus");var inputs=(await obs.Request("GetInputList")).GetProperty("inputs");var browser=new List<object>();foreach(var item in inputs.EnumerateArray()){if(item.GetProperty("inputKind").GetString()!="browser_source")continue;string name=item.GetProperty("inputName").GetString()!;if(!name.StartsWith("Solo Camera"))continue;var settings=(await obs.Request("GetInputSettings",new{inputName=name})).GetProperty("inputSettings");var filters=await obs.Request("GetSourceFilterList",new{sourceName=name});browser.Add(new{name,width=settings.TryGetProperty("width",out var w)?w.GetInt32():0,height=settings.TryGetProperty("height",out var h)?h.GetInt32():0,fps=settings.TryGetProperty("fps",out var f)?f.GetInt32():0,filters});}await File.WriteAllTextAsync(report,JsonSerializer.Serialize(new{stats,video,webcam,browser},new JsonSerializerOptions{WriteIndented=true}));}catch(Exception e){await File.WriteAllTextAsync(report,"FAIL "+e.Message);}}
}
